    a1_sc,
    a1_sd,
    a1_sh,
    a1_sw,
    w1_ptr,
    w1_s0,
    w1_s1,
    w1_sd,
    w1_sh,
    w1_sw,
    a2_ptr,
    a2_sn,
    a2_sc,
    a2_sd,
