                base2 = n * a2_sn + id_ * a2_sd + ih * a2_sh + iw * a2_sw
                k1 = kd * w1_sd + kh * w1_sh + kw * w1_sw
                k2 = kd * w2_sd + kh * w2_sh + kw * w2_sw

                # ---- channel reduction (implicit GEMM over channel tiles) ---
                for cc in range(tl.cdiv(CA_g, 32)):
                    cidx = cc * 32 + tl.arange(0, 32)
                    cmask = cidx < CA_g
