# Degenerate grad_ggO fill (bias broadcast or zeros).
# ---------------------------------------------------------------------------
@triton.jit
def _fill_kernel(
    b_ptr,
    b_s0,
    o_ptr,
    total,
    NSPAT,
    C,
    BLOCK: tl.constexpr,
    HAS_B: tl.constexpr,
):
    pid = tl.program_id(0)
    idx = (pid * BLOCK + tl.arange(0, BLOCK)).to(tl.int64)
    mask = idx < total
    if HAS_B:
        co = (idx // NSPAT) % C
        v = tl.load(b_ptr + co * b_s0, mask=mask, other=0.0)
    else:
        v = tl.zeros((BLOCK,), dtype=tl.float32)
    tl.store(o_ptr + idx, v.to(o_ptr.dtype.element_ty), mask=mask)


# ---------------------------------------------------------------------------
# Layout normalisation: NCHW -> DHWC copy (device kernel, no host fallback).
# ---------------------------------------------------------------------------
@triton.jit
def _chlast_kernel(
    x_ptr,
    o_ptr,
    C,
    S,
    D,
    H,
    W,
    x_sn,
    x_sc,
    x_sd,
    x_sh,
    x_sw,
    BC: tl.constexpr,
    BS: tl.constexpr,
):
    pid_n = tl.program_id(0)
    pid_c = tl.program_id(1)
    pid_s = tl.program_id(2)
    c = pid_c * BC + tl.arange(0, BC)
    s = pid_s * BS + tl.arange(0, BS)
    mc = c < C
    ms = s < S
    sw = s % W
    sh = (s // W) % H
    sd = s // (H * W)
    src = (
        pid_n * x_sn + (sd * x_sd + sh * x_sh + sw * x_sw)[None, :] + c[:, None] * x_sc
    )
    v = tl.load(x_ptr + src, mask=mc[:, None] & ms[None, :], other=0.0)
    vt = tl.trans(v)
    dst = pid_n * S * C + s[:, None] * C + c[None, :]
    tl.store(o_ptr + dst, vt, mask=ms[:, None] & mc[None, :])


@triton.jit
def _wperm_kernel(
    w_ptr,
    o_ptr,
    CI,
    CO,
    K,
    KD,
    KH,
    KW,
    w_s0,
    w_s1,
    w_sd,
    w_sh,
    w_sw,
    BCI: tl.constexpr,
    BCO: tl.constexpr,
    SWAP: tl.constexpr,
):
    """weight -> out[k, C_in, C_out] contiguous.

    SWAP=False: weight is [C_in, C_out, k] (transposed convolution).
    SWAP=True : weight is [C_out, C_in, k] (regular convolution).
    """
    pid_k = tl.program_id(0)
    pid_i = tl.program_id(1)
    pid_o = tl.program_id(2)
    kd = pid_k // (KH * KW)
    kh = (pid_k // KW) % KH
    kw = pid_k % KW
    koff = kd * w_sd + kh * w_sh + kw * w_sw
    ci = pid_i * BCI + tl.arange(0, BCI)
    co = pid_o * BCO + tl.arange(0, BCO)
    mci = ci < CI
    mco = co < CO
    if SWAP:
        off = koff + co[None, :] * w_s0 + ci[:, None] * w_s1
    else:
        off = koff + ci[:, None] * w_s0 + co[None, :] * w_s1
    v = tl.load(w_ptr + off, mask=mci[:, None] & mco[None, :], other=0.0)
    tl.store(
        o_ptr + pid_k * (CI * CO) + ci[:, None] * CO + co[None, :],
        v,
        mask=mci[:, None] & mco[None, :],
    )


# ---------------------------------------------------------------------------
# host helpers
# ---------------------------------------------------------------------------
def _triple(v, nd):
    if isinstance(v, (list, tuple)):
        vals = [int(x) for x in v]
    else:
        vals = [int(v)] * nd
    if len(vals) == 1 and nd > 1:
        vals = vals * nd
    return vals[-3:]


def _spatial(v, nd, fill):
    """Expand one per-axis parameter to the (D, H, W) layout.

    ``fill`` is applied to the synthesised leading axes: stride/dilation use 1,
    padding uses 0.
    """
    vals = _triple(v, nd)
    if nd == 3:
        return vals[0], vals[1], vals[2]
    if nd == 2:
        return fill, vals[-2], vals[-1]
    return fill, fill, vals[-1]


def _v5(t, nd):
    if nd == 1:
        return t.unsqueeze(2).unsqueeze(2)
    if nd == 2:
        return t.unsqueeze(2)
    return t


def _p2(x, hi=64):
    v = 16
    x = int(x)
    while v < x and v < hi:
        v *= 2
    return v


def _p2w(x, hi=128):
    v = 16
    x = int(x)
    while v < x and v < hi:
        v *= 2
    return v


def _spec(t5):
    """(D, H, W, C_in) of a 5-D NCHW tensor."""
    return (int(t5.shape[2]), int(t5.shape[3]), int(t5.shape[4]), int(t5.shape[1]))


def _dhwc(t5):
    """Channel-last [N, D, H, W, C] copy of a 5-D NCHW tensor (device kernel)."""
    N, C = int(t5.shape[0]), int(t5.shape[1])
    D, H, W = int(t5.shape[2]), int(t5.shape[3]), int(t5.shape[4])
    S = D * H * W
    out = torch.empty((N, D, H, W, C), dtype=t5.dtype, device=t5.device)
    if N == 0 or C == 0 or S == 0:
        return out
    BC = _p2(C, 64)
    BS = 64
    grid = (N, triton.cdiv(C, BC), triton.cdiv(S, BS))
    _chlast_kernel[grid](
        t5,
        out,
        C,
        S,
        D,
        H,
        W,
        int(t5.stride(0)),
        int(t5.stride(1)),
        int(t5.stride(2)),
        int(t5.stride(3)),
        int(t5.stride(4)),
        BC=BC,
        BS=BS,
    )
    return out


def _dhwc_strides(t5):
    """(n, c, d, h, w) strides of a channel-last tensor in kernel order."""
    return (
        int(t5.stride(0)),
        int(t5.stride(4)),
        int(t5.stride(1)),
        int(t5.stride(2)),
        int(t5.stride(3)),
    )


def _wperm(w5, transposed):
    """weight -> ([K, C_in, C_out] contiguous copy, (KD, KH, KW)).

    ``transposed=False`` weights are [C_out, C_in, k]; ``transposed=True``
    weights are [C_in, C_out, k].  The copy always exposes C_out innermost.
    """
    if transposed:
        CI, CO = int(w5.shape[0]), int(w5.shape[1])
    else:
        CI, CO = int(w5.shape[1]), int(w5.shape[0])
    KD, KH, KW = int(w5.shape[2]), int(w5.shape[3]), int(w5.shape[4])
    K = KD * KH * KW
    out = torch.empty((K, CI, CO), dtype=w5.dtype, device=w5.device)
    if K == 0 or CI == 0 or CO == 0:
        return out, (KD, KH, KW)
    BCI = _p2(CI, 64)
    BCO = _p2(CO, 64)
    grid = (K, triton.cdiv(CI, BCI), triton.cdiv(CO, BCO))
    _wperm_kernel[grid](
        w5,
        out,
        CI,
        CO,
        K,
        KD,
        KH,
        KW,
        int(w5.stride(0)),
        int(w5.stride(1)),
        int(w5.stride(2)),
        int(w5.stride(3)),
        int(w5.stride(4)),
        BCI=BCI,
        BCO=BCO,
        SWAP=not transposed,
    )
    return out, (KD, KH, KW)


def _wstrides(wt, wdims):
    """(ci, co, kd, kh, kw) strides of a [K, C_in, C_out] normalised weight."""
    KD, KH, KW = wdims
    sk = int(wt.stride(0))
    return (int(wt.stride(1)), int(wt.stride(2)), KH * KW * sk, KW * sk, sk)


def _conv_op(
    out5,
    a1,
    a1dims,
    w1,
    w1dims,
    a2,
    a2dims,
    w2,
    w2dims,
    has_b,
    bias,
    transposed,
    groups,
    S,
    P,
    Dl,
):
    N = int(out5.shape[0])
    OD, OH, OW = int(out5.shape[2]), int(out5.shape[3]), int(out5.shape[4])
    C_out_g = int(out5.shape[1]) // groups
    ID, IH, IW, C_in = a1dims
    CA_g = C_in // groups
    KD, KH, KW = w1dims
    NSPAT = OD * OH * OW
    M = N * NSPAT
    if M == 0 or C_out_g == 0 or CA_g == 0 or KD * KH * KW == 0:
        return
    grid = lambda meta: (
        triton.cdiv(M, meta["BM"]),
        triton.cdiv(C_out_g, meta["BN"]),
        groups,
    )
    has_t2 = a2 is not None
    if has_t2:
        a2p, a2sn, a2sc, a2sd, a2sh, a2sw = (a2,) + _dhwc_strides(a2)
        w2p, w2s0, w2s1, w2sd, w2sh, w2sw = (w2,) + _wstrides(w2, w2dims)
    else:
        a2p, a2sn, a2sc, a2sd, a2sh, a2sw = (a1,) + _dhwc_strides(a1)
        w2p, w2s0, w2s1, w2sd, w2sh, w2sw = (w1,) + _wstrides(w1, w1dims)
    if has_b:
        bp, bs0 = bias, int(bias.stride(0))
    else:
        bp, bs0 = out5, 0

    _conv_out_kernel[grid](
        a1,
        *_dhwc_strides(a1),
        w1,
        *_wstrides(w1, w1dims),
        a2p,
        a2sn,
        a2sc,
        a2sd,
        a2sh,
        a2sw,
        w2p,
        w2s0,
        w2s1,
        w2sd,
        w2sh,
        w2sw,
        bp,
        bs0,
        out5,
        *out5.stride(),
        N,
        OD,
        OH,
        OW,
        ID,
        IH,
        IW,
        KD,
        KH,
        KW,
        C_out_g,
        CA_g,
        S[0],
        S[1],
        S[2],
        P[0],
        P[1],
        P[2],
        Dl[0],
        Dl[1],
        Dl[2],
        NSPAT,
        TRANSPOSED=transposed,
        HAS_T2=has_t2,
        HAS_B=has_b,
    )


def _weight_grad_op(out5, g5, x5, xdims, groups, S, P, Dl):
    N = int(g5.shape[0])
    GD, GH, GW = int(g5.shape[2]), int(g5.shape[3]), int(g5.shape[4])
    XD, XH, XW = xdims
    KD, KH, KW = int(out5.shape[2]), int(out5.shape[3]), int(out5.shape[4])
    A_total = int(out5.shape[0])
    B_g = int(out5.shape[1])
    A_g = A_total // groups
    KFLAT = KD * KH * KW
    R = N * GD * GH
    if R == 0 or A_g == 0 or B_g == 0 or KFLAT == 0 or GW == 0:
        return
    BA = _p2(A_g)
    BB = _p2(B_g)
    BM = _p2w(GW)
    t1 = triton.cdiv(A_g, BA)
    t2 = triton.cdiv(B_g, BB)
    progs = t1 * t2 * KFLAT * groups
    split = 1
    if progs < 64:
        split = min(64, (64 + progs - 1) // progs, R)
    numel = int(out5.numel())
    xst = _dhwc_strides(x5)
    if split > 1:
        part = torch.empty((split, numel), dtype=torch.float32, device=out5.device)
        rw = triton.cdiv(R, split)
        grid = (t1, t2, KFLAT * groups * split)
        _weight_grad_kernel[grid](
            g5,
            *g5.stride(),
            x5,
            *xst,
            part,
            *out5.stride(),
            numel,
            GD,
            GH,
            GW,
            XD,
            XH,
            XW,
            KD,
            KH,
            KW,
            A_g,
            B_g,
            S[0],
            S[1],
            S[2],
            P[0],
            P[1],
            P[2],
            Dl[0],
            Dl[1],
            Dl[2],
            R,
            rw,
            split,
            BA=BA,
            BB=BB,
            BM=BM,
            PARTIAL=True,
        )
        BLOCK = 512
        _wgrad_reduce_kernel[(triton.cdiv(numel, BLOCK),)](
            part, out5, numel, split, BLOCK=BLOCK
        )
    else:
        grid = (t1, t2, KFLAT * groups)
        _weight_grad_kernel[grid](
            g5,
            *g5.stride(),
            x5,
            *xst,
            out5,
            *out5.stride(),
            0,
            GD,
            GH,
            GW,
            XD,
            XH,
            XW,
            KD,
            KH,
            KW,
            A_g,
            B_g,
            S[0],
            S[1],
            S[2],
            P[0],
            P[1],
            P[2],
            Dl[0],
            Dl[1],
            Dl[2],
            R,
            R,
            1,
            BA=BA,
            BB=BB,
            BM=BM,
            PARTIAL=False,
        )


def _fill_out(out, ggb):
    total = out.numel()
    if total == 0:
        return
    C = int(out.shape[1])
    nspat = total // (int(out.shape[0]) * C)
    BLOCK = 512
    grid = (triton.cdiv(total, BLOCK),)
    if ggb is not None:
        _fill_kernel[grid](
            ggb, int(ggb.stride(0)), out, total, nspat, C, BLOCK=BLOCK, HAS_B=True
        )
    else:
        _fill_kernel[grid](out, 0, out, total, nspat, C, BLOCK=BLOCK, HAS_B=False)


# ---------------------------------------------------------------------------
# entry point
# ---------------------------------------------------------------------------
def _convolution_double_backward(
    ggI,
    ggW,
    ggb,
    gO,
    weight,
    self,
    stride,
    padding,
    dilation,
    transposed,
    output_padding,
    groups,
    output_mask,
):
    transposed = bool(transposed)
    groups = int(groups)
    # aten::_convolution_double_backward materialises an output whenever the
    # optional second gradients it needs are present; output_mask does not gate
    # them.  Reproduce that exactly.
    m0 = ggI is not None or ggW is not None or ggb is not None
    m1 = ggW is not None
    m2 = ggI is not None

    nd = gO.dim() - 2
    S = _spatial(stride, nd, 1)
    P = _spatial(padding, nd, 0)
    Dl = _spatial(dilation, nd, 1)

    gO5 = _v5(gO, nd)
    X5 = _v5(self, nd)
    W5 = _v5(weight, nd)
    ggI5 = _v5(ggI, nd) if ggI is not None else None
    ggW5 = _v5(ggW, nd) if ggW is not None else None

    ch = {}
    wpc = {}

    def chlast(t5):
        key = id(t5)
        if key not in ch:
            ch[key] = _dhwc(t5)
        return ch[key]

    def wpermed(t5, tr):
        key = (id(t5), tr)
        if key not in wpc:
            wpc[key] = _wperm(t5, tr)
        return wpc[key]

    # ---- grad_ggO ---------------------------------------------------------
    grad_ggO = None
    if m0:
        out = torch.empty(gO.shape, dtype=gO.dtype, device=gO.device)
        out5 = _v5(out, nd)
        a1 = None
        if out.numel() != 0 and int(gO.shape[1]) != 0:
            if ggI is not None:
                a1 = chlast(ggI5)
                a1d = _spec(ggI5)
                w1, w1d = wpermed(W5, transposed)
                if ggW is not None:
                    a2, a2d = chlast(X5), _spec(X5)
                    w2, w2d = wpermed(ggW5, transposed)
                else:
                    a2, a2d, w2, w2d = None, None, None, None
            elif ggW is not None:
                a1 = chlast(X5)
                a1d = _spec(X5)
                w1, w1d = wpermed(ggW5, transposed)
                a2, a2d, w2, w2d = None, None, None, None
            else:
                a1 = None
            if a1 is not None:
                _conv_op(
                    out5,
                    a1,
                    a1d,
                    w1,
                    w1d,
                    a2,
                    a2d,
                    w2,
                    w2d,
                    ggb is not None,
                    ggb,
                    transposed,
                    groups,
                    S,
                    P,
                    Dl,
                )
            else:
                _fill_out(out, ggb)
        grad_ggO = out

    # ---- grad_self --------------------------------------------------------
    grad_self = None
    if m1:
        out = torch.empty(self.shape, dtype=self.dtype, device=self.device)
        out5 = _v5(out, nd)
        if out.numel() != 0 and int(self.shape[1]) != 0:
            w1, w1d = wpermed(ggW5, not transposed)
            _conv_op(
                out5,
                chlast(gO5),
                _spec(gO5),
                w1,
                w1d,
                None,
                None,
                None,
                None,
                False,
                None,
                not transposed,
                groups,
                S,
                P,
                Dl,
            )
        grad_self = out

    # ---- grad_weight ------------------------------------------------------
    grad_weight = None
    if m2:
        out = torch.empty(weight.shape, dtype=weight.dtype, device=weight.device)
        out5 = _v5(out, nd)
        if out.numel() != 0:
            if transposed:
                g5, x5 = ggI5, gO5
            else:
                g5, x5 = gO5, ggI5
            _weight_grad_op(out5, g5, chlast(x5), _spec(x5)[:3], groups, S, P, Dl)
        grad_weight = out

    return grad_ggO, grad_self, grad_weight
